  Lemma seg_rom_bss_tab : ltac2:(zQ "d0!igd!kp9!in1!kpf!hva!ig7!h9!ku9!lic!lj2!ln3!ig1!lne>1z$6>0@2$4@2$b+ipvgl8^1@2$c^1+mpvgl8@3$5@1$3@1$1@1$0#8@2$a$7@1$8^2@2$2@1$1@1$0#8@1$9Z").
  Proof.
    intros z Hz. unfold PropExec.seg_rom, memory_read. rewrite wa_unsigned by lia. change (Z.of_N 1) with 1.
    replace (find_segment ASEGS z 1) with (Some AsanUbsan_segment_003).
    2:{ rewrite asan_segs_eq. cbn -[Z.leb Z.add Z.of_N]. cbn [Z.of_N seg_base seg_size AsanUbsan_segment_000 AsanUbsan_segment_001 AsanUbsan_segment_002 AsanUbsan_segment_003].
        destruct (Z.leb_spec 65536 z); destruct (Z.leb_spec (z + 1) (65536 + 356352)); cbn [andb]; try lia;
        destruct (Z.leb_spec 421888 z); destruct (Z.leb_spec (z + 1) (421888 + 1323008)); cbn [andb]; try lia;
        destruct (Z.leb_spec 1744896 z); destruct (Z.leb_spec (z + 1) (1744896 + 40960)); cbn [andb]; try lia;
        destruct (Z.leb_spec 1785856 z); destruct (Z.leb_spec (z + 1) (1785856 + 5632000)); cbn [andb]; try lia. reflexivity. }
    replace (seg_readable AsanUbsan_segment_003) with true by reflexivity.
    cbn [seg_bytes seg_base N.to_nat Pos.to_nat Pos.iter_op segment_read_bytes AsanUbsan_segment_003].
    change (Z.of_N 1785856%N) with 1785856.
    cbn [AsanUbsan_segment_003 seg_bytes]. change (N.to_nat 1) with 1%nat. cbn [segment_read_bytes].
    match goal with |- context [segment_byte_at ?l ?o] => replace (segment_byte_at l o) with (Some (b8 0)); [reflexivity|] end.
    symmetry. eapply (AsanHexTree.segment_byte_at_zero_pt _ _ _ _ BsMainIfaceDepotScan.tab_zero_scan); [rewrite asan_len3; cbn; lia | lia].
  Qed.
